<?php $title=t('pay.payslip',['id'=>$row['id']]); require __DIR__.'/header.php'; ?>
<div class="page-heading"><div><span class="eyebrow"><?= h(t('pay.title')) ?></span><h1><?= h($title) ?></h1><p><?= h($row['first_name'].' '.$row['last_name'].' · '.$row['employee_number']) ?></p></div><span class="badge"><?= h(t('pay.'.$row['status'])) ?></span></div>
<p><a class="text-link" href="/payroll">← <?= h(t('pay.title')) ?></a></p>
<?php if (getenv('SETTLEMENT_ENABLED') === '1' && $row['status'] === 'published'): ?><p><a class="button primary" href="/payslips/<?= h($row['id']) ?>/settlement"><?= h(t('settle.title')) ?></a></p><?php endif; ?>
<section class="card detail-card"><dl class="detail-grid"><div><dt><?= h(t('pay.period')) ?></dt><dd><?= h(substr($row['month_start'],0,7)) ?></dd></div><div><dt><?= h(t('pay.version')) ?></dt><dd><?= h($row['version_no']) ?></dd></div>
<?php foreach (['base_amount'=>'base','bonus_amount'=>'bonus','deduction_amount'=>'deduction','gross_amount'=>'gross','net_amount'=>'net'] as $key=>$label): ?><div><dt><?= h(t('pay.'.$label)) ?></dt><dd><?= h(\App\Finance\Money::format($row[$key],$row['currency'])) ?></dd></div><?php endforeach; ?>
<div><dt><?= h(t('pay.prepared_at')) ?></dt><dd><?= h($row['prepared_at']) ?> UTC</dd></div></dl><p class="muted"><?= h(t('pay.immutable')) ?></p></section>
<?php $actions=[]; $own=(int)$user['employee_id']===(int)$row['employee_id'];
if (!$own && $row['status']==='prepared' && \App\Auth\AuthService::can($user,'payslip.verify')) { $actions[]='verified'; }
if (!$own && $row['status']==='verified' && (int)$user['employee_id']!==(int)$row['preparer_employee_id'] && \App\Auth\AuthService::can($user,'payslip.decide')) { $actions[]='approved'; $actions[]='rejected'; }
if (!$own && $row['status']==='approved' && \App\Auth\AuthService::can($user,'payslip.publish')) { $actions[]='published'; }
if ($actions!==[]): ?><section class="card form-card"><h2><?= h(t('pay.workflow')) ?></h2><form method="post" action="/payslips/<?= h($row['id']) ?>/transition"><?= csrfField() ?><div class="field"><label for="reason"><?= h(t('comp.decision_reason')) ?></label><textarea id="reason" name="reason" rows="3" maxlength="2000" required></textarea></div><div class="hr-actions"><?php foreach ($actions as $action): ?><button class="button <?= $action==='rejected' ? 'secondary' : 'primary' ?>" name="event" value="<?= h($action) ?>"><?= h(t('pay.action_'.$action)) ?></button><?php endforeach; ?></div></form></section><?php endif; ?>
<section class="card table-card"><h2 class="comp-section-title"><?= h(t('pay.calendar')) ?></h2><div class="table-scroll"><table><thead><tr><th><?= h(t('comp.date')) ?></th><th><?= h(t('comp.monthly_amount')) ?></th><th><?= h(t('pay.paid')) ?></th></tr></thead><tbody><?php foreach ($row['snapshot']['days'] as $day): ?><tr><td><?= h($day['date']) ?></td><td><?= h(\App\Finance\Money::format($day['monthly_amount'],'MAD')) ?></td><td><?= h(t($day['paid'] ? 'pay.yes' : 'pay.no')) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card table-card"><h2 class="comp-section-title"><?= h(t('comp.events')) ?></h2><div class="table-scroll"><table><thead><tr><th><?= h(t('comp.event')) ?></th><th><?= h(t('comp.decision_reason')) ?></th><th><?= h(t('comp.actor')) ?></th><th><?= h(t('comp.date')) ?></th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= h(t('pay.'.$event['event_type'])) ?></td><td class="comp-text"><?= h($event['reason']) ?></td><td>#<?= h($event['actor_id']) ?></td><td><?= h($event['occurred_at']) ?> UTC</td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card table-card"><h2 class="comp-section-title"><?= h(t('pay.versions')) ?></h2><div class="table-scroll"><table><thead><tr><th><?= h(t('pay.version')) ?></th><th><?= h(t('pay.net')) ?></th><th><?= h(t('common.actions')) ?></th></tr></thead><tbody><?php foreach ($versions as $version): ?><tr><td><?= h($version['version_no']) ?></td><td><?= h(\App\Finance\Money::format($version['net_amount'],$version['currency'])) ?></td><td><a class="text-link" href="/payslips/<?= h($version['id']) ?>"><?= h(t('comp.view')) ?></a></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php require __DIR__.'/footer.php'; ?>
